        when "ru"
          [
            rule_section(:goal, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0444\u0430\u0440\u043A\u043B\u0435 \u0431\u0440\u043E\u0441\u0430\u044E\u0442 \u0448\u0435\u0441\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442 \u0442\u0435, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u043E\u0447\u043A\u0438. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0438\u043B\u0438 \u0440\u0438\u0441\u043A\u043D\u0443\u0442\u044C \u043D\u043E\u0432\u044B\u043C \u0431\u0440\u043E\u0441\u043A\u043E\u043C. \u041D\u0435\u0443\u0434\u0430\u0447\u0430 \u0441\u0436\u0438\u0433\u0430\u0435\u0442 \u0432\u0441\u0435 \u043E\u0447\u043A\u0438 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430, \u043D\u043E \u043D\u0435 \u0437\u0430\u0442\u0440\u0430\u0433\u0438\u0432\u0430\u0435\u0442 \u0443\u0436\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435.",
              "\u0418\u0433\u0440\u0430 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D\u0430 \u043D\u0430 \u0434\u0432\u0443\u0445 \u2014 \u0432\u043E\u0441\u044C\u043C\u0435\u0440\u044B\u0445. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0446\u0435\u043B\u044C \u2014 1000 \u043E\u0447\u043A\u043E\u0432. \u0414\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0432 \u0435\u0451, \u0438\u0433\u0440\u043E\u043A \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043F\u0430\u0440\u0442\u0438\u0438: \u043D\u0430\u0447\u0430\u0442\u044B\u0439 \u043A\u0440\u0443\u0433 \u0434\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F, \u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043E\u0431\u043B\u0430\u0434\u0430\u0442\u0435\u043B\u044C \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u043E\u0433\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430."),
            rule_section(:turn, "\u0411\u0440\u043E\u0441\u043E\u043A, \u0432\u044B\u0431\u043E\u0440 \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435",
              "\u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter: \u0431\u0443\u0434\u0443\u0442 \u0431\u0440\u043E\u0448\u0435\u043D\u044B \u0432\u0441\u0435 \u0448\u0435\u0441\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0441\u043F\u0438\u0441\u043E\u043A \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432. \u0412 \u043A\u0430\u0436\u0434\u043E\u043C \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u0435\u043D\u044B \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u043C\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043D\u0438\u0445. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter.",
              "\u0417\u0430 \u043E\u0434\u0438\u043D \u0432\u044B\u0431\u043E\u0440 \u0432\u044B \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0435 \u0441\u0440\u0430\u0437\u0443 \u0432\u0435\u0441\u044C \u043D\u0443\u0436\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u0438\u0437 \u044D\u0442\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430. \u042D\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043E\u0434\u043D\u0430 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u044F \u0438\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0435\u0434\u0438\u043D\u0438\u0446\u0430 \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0442\u0440\u0435\u043C\u044F \u043F\u044F\u0442\u0451\u0440\u043A\u0430\u043C\u0438. \u041E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u0432\u0441\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043D\u044B\u0435 \u043F\u0440\u0438\u043D\u0435\u0441\u0442\u0438 \u043E\u0447\u043A\u0438 \u043A\u0443\u0431\u0438\u043A\u0438 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E.",
              "\u0422\u0435\u043F\u0435\u0440\u044C \u0440\u0435\u0448\u0438\u0442\u0435, \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0442\u044C \u043B\u0438. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 \u0431\u0440\u043E\u0441\u043E\u043A \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u0447\u0442\u043E\u0431\u044B \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043A\u0443\u0431\u0438\u043A\u0438. \u0415\u0441\u043B\u0438 \u043D\u0430\u0431\u0440\u0430\u043D \u043D\u0443\u0436\u043D\u044B\u0439 \u043C\u0438\u043D\u0438\u043C\u0443\u043C, \u0432\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435: \u043E\u0447\u043A\u0438 \u0434\u043E\u0431\u0430\u0432\u044F\u0442\u0441\u044F \u043A \u0432\u0430\u0448\u0435\u043C\u0443 \u043E\u0431\u0449\u0435\u043C\u0443 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0443, \u0430 \u0445\u043E\u0434 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u043E\u0432\u044B\u0439 \u0431\u0440\u043E\u0441\u043E\u043A \u0434\u043E\u043B\u0436\u0435\u043D \u0441\u0430\u043C \u0434\u0430\u0442\u044C \u043E\u0447\u043A\u0438. \u0415\u0433\u043E \u043D\u0435\u043B\u044C\u0437\u044F \u0441\u043E\u0435\u0434\u0438\u043D\u044F\u0442\u044C \u0441 \u0440\u0430\u043D\u0435\u0435 \u043E\u0442\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u043C\u0438 \u043A\u0443\u0431\u0438\u043A\u0430\u043C\u0438 \u0434\u043B\u044F \u043D\u043E\u0432\u043E\u0439 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438. \u0415\u0441\u043B\u0438 \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u043E\u0447\u043A\u0430 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F, \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442 \u0444\u0430\u0440\u043A\u043B: \u0432\u0435\u0441\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u044D\u0442\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0442\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0438 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0441\u0440\u0430\u0437\u0443 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432\u044B\u043F\u0430\u043B\u0438 1, 2, 4, 5, 5, 5. \u0415\u0434\u0438\u043D\u0438\u0446\u0430 \u0438 \u0442\u0440\u0438 \u043F\u044F\u0442\u0451\u0440\u043A\u0438 \u0434\u0430\u044E\u0442 60 \u043E\u0447\u043A\u043E\u0432; \u043F\u043E\u0441\u043B\u0435 \u0438\u0445 \u0432\u044B\u0431\u043E\u0440\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0434\u0432\u0430 \u043A\u0443\u0431\u0438\u043A\u0430. \u041C\u043E\u0436\u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C 60 \u0438\u043B\u0438 \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u044D\u0442\u0438 \u0434\u0432\u0430. \u0415\u0441\u043B\u0438 \u0432\u044B\u043F\u0430\u0434\u0443\u0442 2 \u0438 6, \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u0431\u0443\u0434\u0435\u0442 \u0438 \u0432\u0441\u0435 60 \u0441\u0433\u043E\u0440\u044F\u0442."),
            rule_section(:banking, "\u041C\u0438\u043D\u0438\u043C\u0443\u043C \u0434\u043B\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F",
              "\u041F\u0435\u0440\u0432\u044B\u0439 \u0440\u0430\u0437 \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u0437\u0430 \u043E\u0434\u0438\u043D \u0445\u043E\u0434 \u0445\u043E\u0442\u044F \u0431\u044B 50 \u043E\u0447\u043A\u043E\u0432. \u041F\u043E\u043A\u0430 \u0432\u0430\u0448 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0439 \u0441\u0447\u0451\u0442 \u0440\u0430\u0432\u0435\u043D \u043D\u0443\u043B\u044E, \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F \u0441 \u043C\u0435\u043D\u044C\u0448\u0438\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u043C \u043D\u0435\u043B\u044C\u0437\u044F \u2014 \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u0431\u0440\u043E\u0441\u0430\u0442\u044C \u0434\u0430\u043B\u044C\u0448\u0435.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0445\u043E\u0434\u0430\u0445 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E 30 \u043E\u0447\u043A\u043E\u0432. \u042D\u0442\u043E \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0437\u0430 \u043D\u043E\u0432\u044B\u0439 \u0445\u043E\u0434, \u0430 \u043D\u0435 \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u043F\u0430\u0440\u0442\u0438\u0438. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u0438 \u043D\u0443\u0436\u043D\u044B\u0439 \u043C\u0438\u043D\u0438\u043C\u0443\u043C, S \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432."),
            rule_section(:scores, "\u041E\u0447\u043A\u0438 \u0437\u0430 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438",
              "\u0412\u0441\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u0432\u044B\u043F\u0430\u0441\u0442\u044C \u0432 \u043E\u0434\u043D\u043E\u043C \u0431\u0440\u043E\u0441\u043A\u0435. \u0415\u0441\u043B\u0438 \u0432\u044B \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442\u0435 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u044B\u0445 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0439, \u0438\u0445 \u043E\u0447\u043A\u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F:",
              "- \u041E\u0434\u043D\u0430 \u0435\u0434\u0438\u043D\u0438\u0446\u0430 \u0434\u0430\u0451\u0442 10 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041E\u0434\u043D\u0430 \u043F\u044F\u0442\u0451\u0440\u043A\u0430 \u0434\u0430\u0451\u0442 5 \u043E\u0447\u043A\u043E\u0432. \u0414\u0440\u0443\u0433\u0438\u0435 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u0434\u0430\u044E\u0442.",
              "- \u0422\u0440\u0438 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0434\u0430\u044E\u0442 75 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0422\u0440\u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442 \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u043D\u0430 \u043E\u0434\u043D\u043E\u043C \u043A\u0443\u0431\u0438\u043A\u0435, \u0443\u043C\u043D\u043E\u0436\u0435\u043D\u043D\u043E\u0435 \u043D\u0430 \u0434\u0435\u0441\u044F\u0442\u044C. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0442\u0440\u0438 \u0434\u0432\u043E\u0439\u043A\u0438 \u2014 20 \u043E\u0447\u043A\u043E\u0432, \u0442\u0440\u0438 \u0448\u0435\u0441\u0442\u0451\u0440\u043A\u0438 \u2014 60.",
              "- \u0427\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442 100 \u043F\u043B\u044E\u0441 \u0434\u0435\u0441\u044F\u0442\u0438\u043A\u0440\u0430\u0442\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0430. \u0427\u0435\u0442\u044B\u0440\u0435 \u0447\u0435\u0442\u0432\u0451\u0440\u043A\u0438 \u2014 140 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041F\u044F\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u0434\u0430\u044E\u0442 300 \u043F\u043B\u044E\u0441 \u0434\u0432\u0430\u0434\u0446\u0430\u0442\u0438\u043A\u0440\u0430\u0442\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0430. \u041F\u044F\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u043E\u043A \u2014 380 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0428\u0435\u0441\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u0434\u0430\u044E\u0442 600 \u043F\u043B\u044E\u0441 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0430, \u0443\u043C\u043D\u043E\u0436\u0435\u043D\u043D\u043E\u0435 \u043D\u0430 25. \u0428\u0435\u0441\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u043E\u043A \u2014 700 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041F\u044F\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439, 1\u20135 \u0438\u043B\u0438 2\u20136, \u0434\u0430\u044E\u0442 100 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0412\u0441\u0435 \u0448\u0435\u0441\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439, 1\u20136, \u0434\u0430\u044E\u0442 200 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0422\u0440\u0438 \u043F\u0430\u0440\u044B \u0440\u0430\u0437\u043D\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u0434\u0430\u044E\u0442 150 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0414\u0432\u0435 \u0442\u0440\u043E\u0439\u043A\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u0434\u0430\u044E\u0442 250 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0427\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043F\u0430\u0440\u043E\u0439 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442 250 \u043E\u0447\u043A\u043E\u0432.",
              "\u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D \u043D\u0430\u0431\u043E\u0440 \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u043F\u043E\u0441\u043E\u0431\u043E\u0432 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430, \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u0430\u043C\u044B\u0439 \u0432\u044B\u0433\u043E\u0434\u043D\u044B\u0439. \u0418\u0442\u043E\u0433\u043E\u0432\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u0441\u0440\u0430\u0437\u0443 \u0443\u043A\u0430\u0437\u0430\u043D\u043E \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432."),
            rule_section(:hot_dice, "\u041A\u043E\u0433\u0434\u0430 \u043E\u0442\u043B\u043E\u0436\u0435\u043D\u044B \u0432\u0441\u0435 \u0448\u0435\u0441\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432",
              "\u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0448\u0435\u0441\u0442\u044C \u043A\u0443\u0431\u0438\u043A\u043E\u0432 \u043F\u0440\u0438\u043D\u0435\u0441\u043B\u0438 \u043E\u0447\u043A\u0438 \u0438 \u0431\u044B\u043B\u0438 \u043E\u0442\u043B\u043E\u0436\u0435\u043D\u044B, \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u043E\u0432\u0430 \u0431\u0440\u043E\u0441\u0430\u0442\u044C \u043F\u043E\u043B\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440. \u041D\u0435\u0432\u0430\u0436\u043D\u043E, \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043B\u0438 \u044D\u0442\u043E \u043E\u0434\u043D\u0438\u043C \u0431\u0440\u043E\u0441\u043A\u043E\u043C \u0438\u043B\u0438 \u0437\u0430 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E. \u041E\u0447\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u0445\u043E\u0434\u0443.",
              "\u0422\u0435\u043F\u0435\u0440\u044C \u0432\u044B\u0431\u0438\u0440\u0430\u0439\u0442\u0435: \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0431\u0440\u043E\u0441\u043E\u043A \u0448\u0435\u0441\u0442\u044C\u044E \u043A\u0443\u0431\u0438\u043A\u0430\u043C\u0438 \u0438\u043B\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435, \u0435\u0441\u043B\u0438 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442 \u043C\u0438\u043D\u0438\u043C\u0443\u043C. \u041F\u0440\u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0438 \u0432\u044B \u0440\u0438\u0441\u043A\u0443\u0435\u0442\u0435 \u0432\u0441\u0435\u043C\u0438 \u043E\u0447\u043A\u0430\u043C\u0438 \u0445\u043E\u0434\u0430, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043D\u0430\u0431\u0440\u0430\u043D\u043D\u044B\u043C\u0438 \u0434\u043E \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u043F\u043E\u043B\u043D\u043E\u0433\u043E \u043D\u0430\u0431\u043E\u0440\u0430."),
            rule_section(:finish, "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043A\u0440\u0443\u0433 \u0438 \u043F\u043E\u0431\u0435\u0434\u0430",
              "\u041A\u043E\u0433\u0434\u0430 \u043F\u043E\u0441\u043B\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0447\u0435\u0439-\u043D\u0438\u0431\u0443\u0434\u044C \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u0435\u0442 1000 \u0438\u043B\u0438 \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0435\u0442 \u0438\u0445, \u0434\u043E\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0430\u0447\u0430\u0442\u044B\u0439 \u043A\u0440\u0443\u0433. \u0425\u043E\u0434\u044F\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u0438, \u0441\u0438\u0434\u044F\u0449\u0438\u0435 \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0433\u043E \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u0434\u043E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u043C\u0435\u0441\u0442\u0430. \u0422\u0435, \u043A\u0442\u043E \u0443\u0436\u0435 \u0445\u043E\u0434\u0438\u043B \u0432 \u044D\u0442\u043E\u043C \u043A\u0440\u0443\u0433\u0435, \u043B\u0438\u0448\u043D\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0438\u0437 \u0447\u0435\u0442\u0432\u0435\u0440\u044B\u0445 1000 \u043D\u0430\u0431\u0440\u0430\u043B \u0432\u0442\u043E\u0440\u043E\u0439. \u0422\u0440\u0435\u0442\u0438\u0439 \u0438 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u044B\u0439 \u0435\u0449\u0451 \u0445\u043E\u0434\u044F\u0442, \u0437\u0430\u0442\u0435\u043C \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u0443 \u043A\u043E\u0433\u043E \u0431\u043E\u043B\u044C\u0448\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432, \u0430 \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u0435\u0440\u0432\u044B\u0439 \u0434\u043E\u0441\u0442\u0438\u0433\u0448\u0438\u0439 \u0446\u0435\u043B\u0438. \u0420\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u043E \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0438\u0447\u044C\u044E."),
            rule_section(:options, "\u0426\u0435\u043B\u044C \u0438 \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0430\u0440\u0442\u0438\u0435\u0439 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0442\u0440\u0438 \u0447\u0438\u0441\u043B\u0430:",
              "- \u0426\u0435\u043B\u044C \u043F\u043E \u043E\u0447\u043A\u0430\u043C, \u043E\u0431\u044B\u0447\u043D\u043E 1000. \u041F\u043E \u0435\u0451 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u043A\u0440\u0443\u0433 \u0438 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B.",
              "- \u041C\u0438\u043D\u0438\u043C\u0443\u043C \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F, \u043E\u0431\u044B\u0447\u043D\u043E 50. \u041E\u043D \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E, \u043F\u043E\u043A\u0430 \u0435\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0439 \u0441\u0447\u0451\u0442 \u0440\u0430\u0432\u0435\u043D \u043D\u0443\u043B\u044E.",
              "- \u041C\u0438\u043D\u0438\u043C\u0443\u043C \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0439, \u043E\u0431\u044B\u0447\u043D\u043E 30. \u041E\u043D \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u043F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F.",
              "\u0414\u0432\u0430 \u043C\u0438\u043D\u0438\u043C\u0443\u043C\u0430 \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E. \u041D\u0443\u043B\u0435\u0432\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043F\u043E\u0440\u043E\u0433, \u043D\u043E \u043F\u0435\u0440\u0435\u0434 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435\u043C \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0437\u0430 \u0445\u043E\u0434 \u0445\u043E\u0442\u044C \u043A\u0430\u043A\u0438\u0435-\u0442\u043E \u043E\u0447\u043A\u0438."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u043C\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438 \u0438\u043B\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435.",
              "Enter: \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043D\u0430\u0431\u043E\u0440 \u043A\u0443\u0431\u0438\u043A\u043E\u0432, \u0431\u0440\u043E\u0441\u043E\u043A \u0438\u043B\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435.",
              "D: \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0431\u0440\u043E\u0441\u043E\u043A.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u043E\u0447\u043A\u0438 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430 \u0438 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0434\u043B\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.")
          ]
        end
      end
    end
